create table public.profiles(
 id uuid primary key references auth.users(id) on delete cascade,
 name text,username text unique,birth_date date,bio text,avatar_url text,city text,region text,current_intention text,availability text,
 is_verified boolean not null default false,
 account_status text not null default 'active' check(account_status in('active','suspended','deleted')),
 created_at timestamptz not null default now(),updated_at timestamptz not null default now()
);

create table public.interests(id bigint generated by default as identity primary key,name text not null unique,slug text not null unique,icon text,created_at timestamptz not null default now());
create table public.profile_interests(user_id uuid not null references public.profiles(id) on delete cascade,interest_id bigint not null references public.interests(id) on delete cascade,created_at timestamptz not null default now(),primary key(user_id,interest_id));
create table public.profile_goals(user_id uuid not null references public.profiles(id) on delete cascade,goal text not null,created_at timestamptz not null default now(),primary key(user_id,goal));

create table public.privacy_settings(
 user_id uuid primary key references public.profiles(id) on delete cascade,
 visibility text not null default 'visible' check(visibility in('visible','connections','invisible')),
 who_can_invite text not null default 'connections' check(who_can_invite in('everyone','connections','nobody')),
 who_can_request_help text not null default 'everyone' check(who_can_request_help in('everyone','connections','nobody')),
 who_can_call text not null default 'connections' check(who_can_call in('connections','nobody')),
 stats_visibility text not null default 'everyone' check(stats_visibility in('everyone','connections','nobody')),
 created_at timestamptz not null default now(),updated_at timestamptz not null default now()
);

create table public.user_locations_private(user_id uuid primary key references public.profiles(id) on delete cascade,location geography(point,4326) not null,accuracy double precision,updated_at timestamptz not null default now());
create index user_locations_private_location_idx on public.user_locations_private using gist(location);
create table public.user_presence(user_id uuid primary key references public.profiles(id) on delete cascade,public_lat double precision,public_lng double precision,presence_status text not null default 'offline' check(presence_status in('online','away','offline')),visible boolean not null default true,last_seen timestamptz,updated_at timestamptz not null default now());

create table public.blocks(blocker_id uuid not null references public.profiles(id) on delete cascade,blocked_id uuid not null references public.profiles(id) on delete cascade,created_at timestamptz not null default now(),primary key(blocker_id,blocked_id),check(blocker_id<>blocked_id));

create table public.connection_requests(
 id uuid primary key default gen_random_uuid(),sender_id uuid not null references public.profiles(id) on delete cascade,receiver_id uuid not null references public.profiles(id) on delete cascade,request_reason text,
 status text not null default 'pending' check(status in('pending','accepted','declined','cancelled')),created_at timestamptz not null default now(),responded_at timestamptz,check(sender_id<>receiver_id)
);
create unique index connection_requests_pending_unique_idx on public.connection_requests(least(sender_id::text,receiver_id::text),greatest(sender_id::text,receiver_id::text)) where status='pending';

create table public.connections(id uuid primary key default gen_random_uuid(),user_a uuid not null references public.profiles(id) on delete cascade,user_b uuid not null references public.profiles(id) on delete cascade,created_at timestamptz not null default now(),unique(user_a,user_b),check(user_a<>user_b));
create unique index connections_pair_unique_idx on public.connections(least(user_a::text,user_b::text),greatest(user_a::text,user_b::text));

create table public.conversations(
 id uuid primary key default gen_random_uuid(),type text not null default 'dm' check(type in('dm','activity','help')),title text,created_by uuid references public.profiles(id) on delete set null,connection_id uuid unique references public.connections(id) on delete cascade,created_at timestamptz not null default now(),updated_at timestamptz not null default now()
);
create table public.conversation_members(conversation_id uuid not null references public.conversations(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,role text not null default 'member',joined_at timestamptz not null default now(),last_read_at timestamptz,primary key(conversation_id,user_id));
create table public.messages(id uuid primary key default gen_random_uuid(),conversation_id uuid not null references public.conversations(id) on delete cascade,sender_id uuid not null references public.profiles(id) on delete cascade,message_type text not null default 'text' check(message_type in('text','image','audio','activity','system')),content text,media_url text,reply_to uuid references public.messages(id) on delete set null,created_at timestamptz not null default now(),edited_at timestamptz,deleted_at timestamptz);
create index messages_conversation_created_idx on public.messages(conversation_id,created_at desc);
create table public.message_reactions(message_id uuid not null references public.messages(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,reaction text not null,created_at timestamptz not null default now(),primary key(message_id,user_id,reaction));

create table public.calls(id uuid primary key default gen_random_uuid(),conversation_id uuid not null references public.conversations(id) on delete cascade,initiator_id uuid not null references public.profiles(id) on delete cascade,call_type text not null check(call_type in('audio','video')),status text not null default 'ringing' check(status in('ringing','accepted','declined','ended','missed')),started_at timestamptz,ended_at timestamptz,created_at timestamptz not null default now());

create table public.activities(
 id uuid primary key default gen_random_uuid(),creator_id uuid not null references public.profiles(id) on delete cascade,title text not null,description text,category text,cover_url text,
 visibility text not null default 'public' check(visibility in('public','connections','private')),activity_type text not null default 'hangout' check(activity_type in('hangout','event','study','sport','project','group')),
 max_participants integer,starts_at timestamptz not null,ends_at timestamptz,region text,status text not null default 'open' check(status in('open','full','cancelled','completed')),created_at timestamptz not null default now(),updated_at timestamptz not null default now()
);
create table public.activity_members(activity_id uuid not null references public.activities(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,role text not null default 'member' check(role in('creator','member')),status text not null default 'confirmed' check(status in('invited','confirmed','removed','cancelled')),joined_at timestamptz not null default now(),primary key(activity_id,user_id));
create table public.activity_invites(id uuid primary key default gen_random_uuid(),activity_id uuid not null references public.activities(id) on delete cascade,sender_id uuid not null references public.profiles(id) on delete cascade,receiver_id uuid not null references public.profiles(id) on delete cascade,status text not null default 'pending' check(status in('pending','accepted','maybe','declined')),created_at timestamptz not null default now(),responded_at timestamptz);
create unique index activity_invites_pending_unique_idx on public.activity_invites(activity_id,receiver_id) where status='pending';

create table public.sos_requests(id uuid primary key default gen_random_uuid(),author_id uuid not null references public.profiles(id) on delete cascade,category text not null,description text not null,help_mode text not null default 'online' check(help_mode in('online','presential','either')),needed_at timestamptz,region text,identity_visibility text not null default 'normal' check(identity_visibility in('normal','first_name','private')),status text not null default 'looking' check(status in('looking','responses','in_progress','resolved','cancelled')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),resolved_at timestamptz);
create table public.sos_responses(id uuid primary key default gen_random_uuid(),sos_id uuid not null references public.sos_requests(id) on delete cascade,helper_id uuid not null references public.profiles(id) on delete cascade,status text not null default 'offered' check(status in('offered','accepted','declined','completed','cancelled')),conversation_id uuid references public.conversations(id) on delete set null,created_at timestamptz not null default now(),responded_at timestamptz,unique(sos_id,helper_id));
create table public.help_skills(id bigint generated by default as identity primary key,name text not null unique,slug text not null unique);
create table public.profile_help_skills(user_id uuid not null references public.profiles(id) on delete cascade,skill_id bigint not null references public.help_skills(id) on delete cascade,primary key(user_id,skill_id));

create table public.reviews(id uuid primary key default gen_random_uuid(),reviewer_id uuid not null references public.profiles(id) on delete cascade,reviewed_user_id uuid not null references public.profiles(id) on delete cascade,rating integer not null check(rating between 1 and 5),comment text,context_type text not null check(context_type in('connection','activity','help','meeting')),context_id uuid not null,created_at timestamptz not null default now(),check(reviewer_id<>reviewed_user_id),unique(reviewer_id,reviewed_user_id,context_type,context_id));
create table public.trust_metrics(user_id uuid primary key references public.profiles(id) on delete cascade,trust_score numeric(5,2) not null default 0,review_count integer not null default 0,completed_activities integer not null default 0,completed_help integer not null default 0,updated_at timestamptz not null default now());

create table public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,actor_id uuid references public.profiles(id) on delete set null,type text not null,title text not null,body text,entity_type text,entity_id uuid,read_at timestamptz,created_at timestamptz not null default now());
create index notifications_user_created_idx on public.notifications(user_id,created_at desc);
create table public.reports(id uuid primary key default gen_random_uuid(),reporter_id uuid not null references public.profiles(id) on delete cascade,reported_user_id uuid not null references public.profiles(id) on delete cascade,reason text not null,description text,target_type text,target_id uuid,status text not null default 'open' check(status in('open','reviewing','resolved','dismissed')),moderator_id uuid references public.profiles(id) on delete set null,moderator_notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());

create table public.trusted_contacts(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,name text not null,phone text,email text,relationship text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.guardian_links(id uuid primary key default gen_random_uuid(),minor_user_id uuid not null references public.profiles(id) on delete cascade,guardian_user_id uuid references public.profiles(id) on delete set null,guardian_name text not null,guardian_phone text,guardian_email text,relationship text,status text not null default 'pending' check(status in('pending','verified','rejected','revoked')),verified_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());

create table public.meeting_sessions(id uuid primary key default gen_random_uuid(),creator_id uuid not null references public.profiles(id) on delete cascade,activity_id uuid references public.activities(id) on delete set null,scheduled_at timestamptz not null,expected_end_at timestamptz not null,place_provider text,place_id text,place_name text,place_address text,place_lat double precision,place_lng double precision,status text not null default 'preparing' check(status in('preparing','ready','active','completed','cancelled')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.meeting_participants(meeting_id uuid not null references public.meeting_sessions(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,status text not null default 'confirmed' check(status in('confirmed','on_the_way','arrived','left','cancelled')),created_at timestamptz not null default now(),primary key(meeting_id,user_id));
create table public.meeting_verifications(id uuid primary key default gen_random_uuid(),meeting_id uuid not null references public.meeting_sessions(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,provider text,provider_reference text,status text not null default 'pending' check(status in('pending','verified','failed')),verified_at timestamptz,created_at timestamptz not null default now(),unique(meeting_id,user_id));
create table public.meeting_checkins(id uuid primary key default gen_random_uuid(),meeting_id uuid not null references public.meeting_sessions(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,type text not null,created_at timestamptz not null default now());
create table public.guardian_share_sessions(id uuid primary key default gen_random_uuid(),minor_user_id uuid not null references public.profiles(id) on delete cascade,guardian_link_id uuid not null references public.guardian_links(id) on delete cascade,meeting_id uuid not null references public.meeting_sessions(id) on delete cascade,token_hash text not null unique,expires_at timestamptz not null,revoked_at timestamptz,created_at timestamptz not null default now());
create table public.security_events(id uuid primary key default gen_random_uuid(),user_id uuid references public.profiles(id) on delete set null,event_type text not null,meeting_id uuid references public.meeting_sessions(id) on delete set null,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
